const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let ptr = 0;
const N = data[ptr++];
const M = data[ptr++];
const V = N * M;

const maxNodes = 2 * V + 5;
const T = new Int32Array(maxNodes);
const W = new Float64Array(maxNodes);
const dsu = new Int32Array(maxNodes);
const parent = new Int32Array(maxNodes);
parent.fill(-1);

for (let i = 0; i < V; i++) {
    const val = data[ptr++];
    T[i] = val;
    W[i] = val;
    dsu[i] = i;
}

const order = new Array(V);
for (let i = 0; i < V; i++) order[i] = i;
order.sort((a, b) => T[a] - T[b]);

const active = new Uint8Array(V);
let nodeCount = V;

function find(x) {
    while (dsu[x] !== x) {
        dsu[x] = dsu[dsu[x]];
        x = dsu[x];
    }
    return x;
}

function addRoot(roots, r) {
    for (let i = 0; i < roots.length; i++) {
        if (roots[i] === r) return;
    }
    roots.push(r);
}

for (let oi = 0; oi < V; oi++) {
    const idx = order[oi];
    const row = Math.floor(idx / M);
    const col = idx % M;

    const roots = [];

    if (col > 0 && active[idx - 1]) addRoot(roots, find(idx - 1));
    if (col + 1 < M && active[idx + 1]) addRoot(roots, find(idx + 1));
    if (row > 0 && active[idx - M]) addRoot(roots, find(idx - M));
    if (row + 1 < N && active[idx + M]) addRoot(roots, find(idx + M));

    const newNode = nodeCount++;
    T[newNode] = T[idx];

    let sum = W[idx];

    parent[idx] = newNode;
    dsu[idx] = newNode;

    for (let i = 0; i < roots.length; i++) {
        const r = roots[i];
        parent[r] = newNode;
        sum += W[r];
        dsu[r] = newNode;
    }

    W[newNode] = sum;
    dsu[newNode] = newNode;
    active[idx] = 1;
}

const out = new Float64Array(nodeCount);

for (let u = nodeCount - 1; u >= 0; u--) {
    const p = parent[u];
    if (p === -1) {
        out[u] = W[u];
    } else {
        if (W[u] >= T[p]) {
            out[u] = out[p];
        } else {
            out[u] = W[u];
        }
    }
}

const lines = [];
for (let i = 0; i < N; i++) {
    const row = [];
    for (let j = 0; j < M; j++) {
        row.push(out[i * M + j]);
    }
    lines.push(row.join(' '));
}

console.log(lines.join('\n'));
